double ft = 0.3048;
string name = Tama.Args.Get(args, "locationName", "");
double tA = Tama.Args.Get(args, "angleDeg", 0.0) * Math.PI / 180;
Func<double,double> wrap = x => Math.Atan2(Math.Sin(x), Math.Cos(x));
ProjectLocation target = null;
foreach (ProjectLocation pl in doc.ProjectLocations) if (pl.Name == name) target = pl;
if (target == null) throw new Exception("Location not found");
if (target.Id == doc.ActiveProjectLocation.Id) throw new Exception("Target is current site - refused.");
var act = doc.ActiveProjectLocation; var actBefore = act.GetProjectPosition(XYZ.Zero);
var sp = new FilteredElementCollector(doc).OfClass(typeof(BasePoint)).Cast<BasePoint>().First(b => b.IsShared);
var spBefore = sp.SharedPosition;

var before = target.GetProjectPosition(XYZ.Zero);
// mirrored site: setter behaves as read_new = 2*read_old - set
var pp = target.GetProjectPosition(XYZ.Zero);
pp.Angle = wrap(2 * before.Angle - tA);
target.SetProjectPosition(XYZ.Zero, pp);
doc.Regenerate();
var r = target.GetProjectPosition(XYZ.Zero);

double errDeg = Math.Abs(wrap(tA - r.Angle)) * 180 / Math.PI;
double errMm = Math.Sqrt(Math.Pow((r.EastWest-before.EastWest)*ft,2)+Math.Pow((r.NorthSouth-before.NorthSouth)*ft,2)+Math.Pow((r.Elevation-before.Elevation)*ft,2))*1000;
if (errDeg > 1e-6 || errMm > 0.5) throw new Exception("Check failed (angle err " + errDeg + " deg, position drift " + errMm + " mm) - rolled back.");
var a2 = act.GetProjectPosition(XYZ.Zero);
if (Math.Abs(a2.EastWest-actBefore.EastWest)+Math.Abs(a2.NorthSouth-actBefore.NorthSouth)+Math.Abs(a2.Elevation-actBefore.Elevation) > 0.003 || Math.Abs(a2.Angle-actBefore.Angle) > 1e-8) throw new Exception("Current site changed - rolled back.");
if (sp.SharedPosition.DistanceTo(spBefore) > 0.003) throw new Exception("Survey point changed - rolled back.");
Func<ProjectPosition, object> f = p => new { ew = Math.Round(p.EastWest*ft,4), ns = Math.Round(p.NorthSouth*ft,4), elev = Math.Round(p.Elevation*ft,4), angle = Math.Round(p.Angle*180/Math.PI,6) };
return new { site = target.Name, before = f(before), after = f(r), current = new { name = act.Name, values = f(a2) } };
